# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.7.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.7"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.7/berth-darwin-arm64.tar.gz"
      sha256 "123660a47edab83a1bceeac8dc501550ad0ee545c438e15f6138becb21601010"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.7/berth-darwin-amd64.tar.gz"
      sha256 "07b5cd65a624e2b60f3ce65e2079a0727dfc7f18be1df63f81b6d4b68b921f79"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.7/berthd-darwin-arm64.tar.gz"
      sha256 "61960e1bb2389ff20868d441d55a7431ed365f7310f6da2baab582a909b10be7"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.7/berthd-darwin-amd64.tar.gz"
      sha256 "717f24de4abcf56c8ebb89d9b78ca8a63deded0c622a6077ba77c0ef60908d17"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.7/berth-linux-arm64.tar.gz"
      sha256 "eddcf5e72f79ca98f330d9d7551e772be66e9fab50dd29a5b5d03a3a7891ee37"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.7/berth-linux-amd64.tar.gz"
      sha256 "2b00d861387889ab4c887a718d79bf98d5ea0ad306dc297517398af7354f8c95"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
